theorem testSet_bddAbove (D : ConstructionData 𝕜) {p : Seminorm 𝕜 (C00 𝕜)}
    (hp : p ≤ mass) : BddAbove (testSet D p) :=
  ⟨mass, fun _ hq => normTest_le_mass D hp hq⟩

