theorem normTest_mono (D : ConstructionData 𝕜) {p q : Seminorm 𝕜 (C00 𝕜)}
    (hpq : p ≤ q) {r : Seminorm 𝕜 (C00 𝕜)} (hr : NormTest D p r) :
    ∃ s, NormTest D q s ∧ r ≤ s
